'valid_topics',(select count(*) from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where t.id in (select (v->>'id')::uuid from jsonb_each('{"texto": {"id": "2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f", "block_name": "Bloco I", "created_at": "2026-09-26T03:57:09.233726+00:00", "discipline": "L\u00edngua Portuguesa", "edition_id": "a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff", "topic_text": "Compreens\u00e3o e interpreta\u00e7\u00e3o de textos de g\u00eaneros variados; reconhecimento de tipos e g\u00eaneros textuais; dom\u00ednio da ortografia oficial e dos mecanismos de coes\u00e3o textual; referencia\u00e7\u00e3o, substitui\u00e7\u00e3o, repeti\u00e7\u00e3o, conectores e sequencia\u00e7\u00e3o; tempos e modos verbais.", "topic_order": 1, "content_status": "current"}, "gramatica": {"id": "5873244d-48e6-4241-a474-b5db3317d27f", "block_name": "Bloco I", "created_at": "2026-09-26T03:57:09.233726+00:00", "discipline": "L\u00edngua Portuguesa", "edition_id": "a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff", "topic_text": "Estrutura morfossint\u00e1tica do per\u00edodo: classes de palavras; coordena\u00e7\u00e3o e subordina\u00e7\u00e3o entre ora\u00e7\u00f5es e termos; pontua\u00e7\u00e3o; concord\u00e2ncia verbal e nominal; reg\u00eancia verbal e nominal; crase; coloca\u00e7\u00e3o dos pronomes \u00e1tonos.", "topic_order": 2, "content_status": "current"}, "reescrita": {"id": "13a80069-1852-447d-a71b-1c8f2489c487", "block_name": "Bloco I", "created_at": "2026-09-26T03:57:09.233726+00:00", "discipline": "L\u00edngua Portuguesa", "edition_id": "a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff", "topic_text": "Reescrita de frases e par\u00e1grafos: significa\u00e7\u00e3o das palavras; substitui\u00e7\u00e3o de palavras ou trechos; reorganiza\u00e7\u00e3o de ora\u00e7\u00f5es e per\u00edodos; reescrita em diferentes g\u00eaneros e n\u00edveis de formalidade. Correspond\u00eancia oficial conforme o Manual de Reda\u00e7\u00e3o da Presid\u00eancia: aspectos gerais, finalidades, linguagem e formato.", "topic_order": 3, "content_status": "current"}}'::jsonb) kv(k,v)) and t.content_status='current' and e.status='active')) as data;
